import json

with open('/root/autodl-tmp/data/re-docred-repo/data/dev_revised.json') as f:
    data = json.load(f)

# Check evidence field format for triples without evidence
no_ev_examples = []
has_ev_examples = []
for doc in data[:5]:
    for lbl in doc.get('labels', []):
        ev = lbl.get('evidence', [])
        if not ev:
            no_ev_examples.append(lbl)
        else:
            has_ev_examples.append(lbl)

print('=== With evidence ===')
for ex in has_ev_examples[:3]:
    print(ex)

print()
print('=== Without evidence ===')
for ex in no_ev_examples[:3]:
    print(ex)

# Check if evidence key exists but empty vs missing
missing_key = 0
empty_list = 0
for doc in data:
    for lbl in doc.get('labels', []):
        if 'evidence' not in lbl:
            missing_key += 1
        elif not lbl['evidence']:
            empty_list += 1
print(f'\nevidence key missing: {missing_key}')
print(f'evidence key present but empty: {empty_list}')
"

